<?php use kartik\select2\Select2;use yii\helpers\Html;use yii\widgets\ActiveForm;$form=ActiveForm::begin()?>
<div class="card card-success card-outline"><div class="card-body"><div class="row"><div class="col-md-6"><?=$form->field($model,'student_id')->widget(Select2::class,['data'=>$students,'options'=>['placeholder'=>'Pilih mahasiswa...'],'pluginOptions'=>['allowClear'=>true]])?><?=$form->field($model,'academic_period')->dropDownList($periods)?><?=$form->field($model,'study_program_id')->widget(Select2::class,['data'=>$programs])?></div><div class="col-md-6"><?=$form->field($model,'entry_year')->textInput(['type'=>'number'])?><?=$form->field($model,'current_semester')->textInput(['type'=>'number'])?><?=$form->field($model,'notes')->textarea(['rows'=>4])?></div></div><hr><h5>Jenis Cekal</h5><div class="row"><?php foreach($model::blockAttributes() as $attribute=>$label):?><div class="col-md-3"><?=$form->field($model,$attribute)->checkbox(['label'=>$label])?></div><?php endforeach?></div><div class="text-right"><?=Html::submitButton('<i class="fas fa-save"></i> Simpan',['class'=>'btn btn-success'])?> <?=Html::a('Batal',['index'],['class'=>'btn btn-warning'])?></div></div></div><?php ActiveForm::end()?>
